 {id="NF-SOLAR-019",itemType="ProjectNightfall.Research_NF_SOLAR_019",distribution={LaboratoryBooks=.025,TestingLab=.01,ArmyStorageMedical=.005},category="SOLAR",classification="SECRET",title="Solar Exposure Anomaly",tier=2,references={"NF-UV-003","NF-ANAT-014"},prerequisiteDocuments={"NF-UV-003"},grantsKnowledge={"ProjectNightfall.NaturalArtificialUVDistinction"},content={"Natural solar exposure and artificial ultraviolet exposure are not equivalent. Transformation events followed only ",{text="prolonged starvation combined with natural solar hibernation",redacted=true,marker="████████████"}," under observed trial conditions."}},
 {id="NF-ANAT-014",itemType="ProjectNightfall.Research_NF_ANAT_014",distribution={LaboratoryBooks=.02,TestingLab=.012,ArmyBunkerMedical=.006},category="ANATOMY",classification="SECRET",title="Post-Hibernation Morphology",tier=3,references={"MORTIS-ANAT-012","NF-SOLAR-019"},prerequisiteDocuments={"NF-SOLAR-019"},grantsKnowledge={"ProjectNightfall.FeralPhysiology"},content={"Starved subjects that rose after repeated solar hibernation displayed a stable predatory phenotype. ",{text="The change was behavioral and metabolic before it was visibly anatomical.",redacted=true,marker="██████████"}," Surface appearance alone cannot identify the transition."}},
 {id="NF-BEHAV-007",itemType="ProjectNightfall.Research_NF_BEHAV_007",distribution={TestingLab=.008,ArmyBunkerMedical=.004},category="BEHAVIOR",classification="BLACK",title="Follower Aggregation",tier=3,references={"NF-ANAT-014","NF-BEHAV-044"},prerequisiteDocuments={"NF-ANAT-014"},grantsKnowledge={"ProjectNightfall.PackDynamics"},content={"Feral subjects accumulated around individuals that retained planning ability. ",{text="Additional cognitive subjects increased the stable follower limit.",redacted=true,marker="████████"}," The aggregation was organized rather than a vanilla rally response."}},
 {id="NF-INCIDENT-052",itemType="ProjectNightfall.Research_NF_INCIDENT_052",distribution={TestingLab=.004,ArmyBunkerMedical=.002},category="INCIDENT",classification="BLACK",title="Containment Pursuit 052",tier=4,references={"NF-BEHAV-007","NF-BEHAV-044"},prerequisiteDocuments={"NF-BEHAV-007"},grantsKnowledge={"ProjectNightfall.PersistentPredation"},content={"The subject abandoned direct pursuit after losing the marked technician. ",{text="Search resumed from concealed positions after repeated rest intervals.",redacted=true,marker="████████████"}," Apparent disengagement must be treated as continuing target-specific intent."}},
 {id="NF-BEHAV-044",itemType="ProjectNightfall.Research_NF_BEHAV_044",distribution={TestingLab=.003,ArmyBunkerMedical=.0015},category="BEHAVIOR",classification="BLACK",title="Cognitive Retention",tier=4,references={"NF-BEHAV-007","NF-INCIDENT-052"},prerequisiteDocuments={"NF-BEHAV-007","NF-INCIDENT-052"},prerequisiteKnowledge={"ProjectNightfall.NaturalArtificialUVDistinction"},grantsKnowledge={"ProjectNightfall.AnomalousFeralCognition"},content={"Subject broke visual contact at 22:14. The team assumed pursuit had ended. ",{text="Subject deliberately concealed its approach and attacked from behind at 22:31.",redacted=true,marker="████████████"}," Loss of visual contact must no longer be interpreted as loss of pursuit."}},
